      "content": "{\n  \"name\": \"dsh-advisor\",\n  \"version\": \"0.7.1\",\n  \"type\": \"module\",\n  \"description\": \"dsh plugin bundle porting the omp advisor subsystem: a per-session reviewer model that observes the primary transcript and injects severity-ranked advice (nit/concern/blocker).\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"https://github.com/omdsh-dev/dsh-advisor\"\n  },\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\"\n  ],\n  \"main\": \"./lib/index.js\",\n  \"types\": \"./lib/index.d.ts\",\n  \"icon\": \"./icon.svg\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": {\n      \"types\": \"./lib/client.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./locale/*.json\": \"./locale/*.json\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"locale\",\n    \"docs/DETAIL.md\",\n    \"docs/DETAIL.zh.md\",\n    \"docs/preview.svg\",\n    \"docs/preview.zh.svg\",\n    \"icon.svg\",\n    \"cordis.patch.yml\",\n    \"scripts\"\n  ],\n  \"scripts\": {\n    \"typecheck\": \"tsc --noEmit && tsc -p tsconfig.client.json --noEmit && tsc -p tsconfig.spec.json --noEmit\",\n    \"build\": \"tsc -p tsconfig.build.json && node scripts/build-client.mjs\",\n    \"prepare\": \"pnpm build\",\n    \"prepack\": \"pnpm build\",\n    \"test\": \"vitest run\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-store\",\n        \"@deepseek-ai/dsh-client-ui-plugin-manager\",\n        \"@deepseek-ai/dsh-client-locale\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.1.0\",\n    \"@deepseek-ai/dsh-agent\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-api-gateway\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-api-remotes\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-api-settings-controller\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-api-session-controller\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-connection\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-locale\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-store\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-plugin-manager\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-commands\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-llm\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-session\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-settings\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-timeout\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-typert-protocol\": \"^0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-typert-registry\": \"^0.2.2-rc.1\",\n    \"react\": \"^18.2.0\",\n    \"@deepseek-ai/schemastery\": \"^3.19.0\"\n  },\n  \"devDependencies\": {\n    \"@testing-library/dom\": \"^10.4.1\",\n    \"@testing-library/react\": \"^16.3.2\",\n    \"@types/node\": \"^26.2.0\",\n    \"@types/react\": \"~18.3.1\",\n    \"@types/react-dom\": \"~18.3.7\",\n    \"esbuild\": \"^0.28.2\",\n    \"jsdom\": \"29.1.1\",\n    \"lightningcss\": \"^1.33.0\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"^18.3.1\",\n    \"typescript\": \"^5.6.0\",\n    \"vitest\": \"^4.1.12\"\n  },\n  \"engines\": {\n    \"node\": \"^22.19 || >=24\"\n  },\n  \"license\": \"MIT\"\n}\n"
